// Embedded image safety net. Used only if a normal local image cannot be loaded.
(function () {
  "use strict";
  const backups = {"akkergeshen.jpg":"data:image/jpeg;base64,","altyn-emel.jpg":"data:image/jpeg;base64,","aruzhan.jpg":"data:image/jpeg;base64,","bayanaul.jpg":"data:image/jpeg;base64,","bektau-ata.jpg":"data:image/jpeg;base64,","bozzhyra.jpg":"data:image/jpeg;base64,","charyn-canyon.jpg":"data:image/jpeg;base64,","kaindy.jpg":"data:image/jpeg;base64,","karkaraly.jpg":"data:image/jpeg;base64,","kolsay-lake.jpg":"data:image/jpeg;base64,","mereilim.jpg":"data:image/jpeg;base64,","samal.jpg":"data:image/jpeg;base64,","turgen.jpg":"data:image/jpeg;base64,"};

  function fileNameFromSource(source) {
    try {
      const url = new URL(source || "", window.location.href);
      return decodeURIComponent(url.pathname.split("/").pop() || "");
    } catch (error) {
      return String(source || "").split("/").pop().split("?")[0].split("#")[0];
    }
  }

  function useEmbeddedBackup(image) {
    if (!image || image.dataset.embeddedBackupApplied === "true") return;
    const fileName = fileNameFromSource(image.getAttribute("src"));
    const backup = backups[fileName];
    if (!backup) return;
    image.dataset.embeddedBackupApplied = "true";
    image.src = backup;
  }

  document.addEventListener("error", function (event) {
    const target = event.target;
    if (target && target.tagName === "IMG") useEmbeddedBackup(target);
  }, true);

  window.addEventListener("DOMContentLoaded", function () {
    document.querySelectorAll("img").forEach(function (image) {
      if (image.complete && image.naturalWidth === 0) useEmbeddedBackup(image);
    });
  });

  window.UK_IMAGE_BACKUPS = backups;
})();
